3	// Öffentlicher Ersparnis-Rechner Energiegemeinschaft Österreich (WP6). Reine Funktion eg/interesse.js rechnerOeffentlich
4	// (= Python eg_portal_kern.rechner_oeffentlich, API POST /api/eg/rechner): Netzentgelt aus der Regeltabelle (SNE-V 2018 bis
5	// Ende 2026, Arbeitshypothese ab 2027), Abgabenbefreiung nur EEG, Standardpreise aus src/lib/invest/markt.js.
6	
7	import { useMemo, useState } from "react";
8	import { AlertTriangle, Info, Leaf, PiggyBank, Sun, Users, Zap } from "lucide-react";
9	import Button from "@/components/ui/Button";
10	import { Auswahl, Gruppe, Kennzahl, Regler, Zahl } from "@/components/Rechner/bausteine";
11	import { ErgebnisKopf, Hinweis, MobilKurz, RechnerRahmen } from "@/components/Rechner/InvestTeile";
12	import { RECHNER_DECKUNG, RECHNER_MODELLE, RECHNER_PROFILE, RECHNER_ROLLEN, RECHNER_STANDARD, rechnerOeffentlich } from "@/lib/plattform/eg/interesse";
13	import { fmt } from "@/lib/rechner/annahmen";
