15	const opt = (o) => Object.entries(o).map(([id, x]) => ({ id, label: typeof x === "string" ? x : x.label, sub: typeof x === "string" ? undefined : x.sub }));
16	const euro = (v) => `${v < 0 ? "−" : ""}${fmt(Math.abs(Math.round(v)))} €`;
