18	export default function ErsparnisRechner({ ctaHref = "/registrieren?rolle=mitglied&weiter=%2Fportal%2Feg%2Fbeitritt" }) {
19	  const [e, setE] = useState({ ...RECHNER_STANDARD });
20	  const set = (k) => (v) => setE((a) => ({ ...a, [k]: v }));
21	  const r = useMemo(() => rechnerOeffentlich(e), [e]);
22	  const verbraucht = e.rolle !== "erzeuger";
23	  const erzeugt = e.rolle !== "verbraucher";
24	  const max = Math.max(1, ...r.teile.map((t) => Math.abs(t.eur)));
25	  return (
26	    <RechnerRahmen
27	      mitlaufend
28	      eingaben={
29	        <>
30	          <MobilKurz werte={[["Vorteil netto", euro(r.nettoEur)], ["aus Gemeinschaft", `${fmt(r.quotePct)} %`], ["CO₂", `${fmt(r.co2Kg)} kg`]]} />
31	          <div className="space-y-8">
32	            <Gruppe titel="Sie">
33	              <Auswahl legende="Rolle" wert={e.rolle} onChange={set("rolle")} optionen={opt(RECHNER_ROLLEN)} klein />
34	              {verbraucht && <Auswahl legende="Verbrauch" wert={e.profil} onChange={set("profil")} optionen={opt(RECHNER_PROFILE)} spalten={2} klein />}
35	              {verbraucht && <Regler label="Jahresverbrauch" wert={e.verbrauchKwh} min={500} max={60000} step={100} format={(v) => `${fmt(v)} kWh`} onChange={set("verbrauchKwh")} hinweis="steht auf Ihrer Jahresabrechnung" />}
36	              {erzeugt && <Regler label="PV-Anlage" wert={e.kwp} min={1} max={500} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} kWp`} onChange={set("kwp")} hinweis={`≈ ${fmt(r.erzeugungKwh)} kWh Erzeugung pro Jahr`} />}
37	              {erzeugt && <Regler label="Eigenverbrauch im Haus" wert={e.eigenverbrauchPct} min={0} max={90} step={5} format={(v) => `${fmt(v)} %`} onChange={set("eigenverbrauchPct")} />}
38	            </Gruppe>
