47	              {verbraucht && <Regler label="Netznutzungs-Arbeitspreis" wert={e.netzApCt} min={2} max={12} step={0.1} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("netzApCt")} hinweis="je Netzgebiet verschieden, siehe Netzrechnung" />}
48	              {erzeugt && <Regler label="Einspeisepreis der Gemeinschaft" wert={e.einspeiseEgCt} min={2} max={15} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("einspeiseEgCt")} />}
49	              {erzeugt && <Regler label="Alternative: Marktpreis Überschuss" wert={e.marktCt} min={0} max={15} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("marktCt")} />}
