62	            <Kennzahl icon={Zap} label="Vorteil je kWh" zusatz="Energie + Netz + Abgabe">{verbraucht ? `${fmt(r.vorteilJeKwhCt, 2)} ct` : "–"}</Kennzahl>
63	            <Kennzahl icon={Leaf} label="CO₂ (rechnerisch)" zusatz="UBA-Faktor, AT eher niedriger"><Zahl wert={r.co2Kg} suffix=" kg" /></Kennzahl>
