69	                <div className="mt-1 h-2 rounded-full bg-ink-100"><div className={t.id === "erzeuger" ? "h-2 rounded-full bg-sun-400" : t.id === "netz" ? "h-2 rounded-full bg-navy-600" : "h-2 rounded-full bg-ov-500"} style={{ width: `${Math.max(2, (Math.abs(t.eur) / max) * 100)}%` }} /></div>
