74	          <div className="mt-4 space-y-2.5">
75	            <Hinweis ton={r.regel.status === "gesichert" ? "neutral" : "warnung"} icon={Info}>Netzentgelt: {r.regel.text}{r.regel.abgabenBefreit ? "; Elektrizitätsabgabe entfällt für Gemeinschaftsstrom" : ""}. Quelle: {r.regel.quelle}.</Hinweis>
76	            {r.hinweise.map((h) => <Hinweis key={h.id} ton={h.id === "negativ" ? "warnung" : "neutral"} icon={h.id === "negativ" ? AlertTriangle : Info}>{h.text}</Hinweis>)}
