.ov-linie { stroke-dasharray: 1; stroke-dashoffset: 0; }
@media (prefers-reduced-motion: no-preference) {
  .js-ready .ov-reveal:not(.is-visible) .ov-balken-y { transform: scaleY(0); }
  .js-ready .ov-reveal:not(.is-visible) .ov-balken-x { transform: scaleX(0); }
  .js-ready .ov-reveal:not(.is-visible) .ov-linie { stroke-dashoffset: 1; }
  .js-ready .ov-reveal:not(.is-visible) .ov-flaeche-ein { opacity: 0; }
  .is-visible .ov-balken-y, .ov-sofort .ov-balken-y, .ov-balken-y.ov-sofort {
    animation: ov-wachsen-y var(--ov-dauer-xl) var(--ov-ease-out) both;
    animation-delay: calc(var(--i, 0) * 40ms + var(--ov-delay, 0ms));
  }
  .is-visible .ov-balken-x, .ov-sofort .ov-balken-x, .ov-balken-x.ov-sofort {
    animation: ov-wachsen-x var(--ov-dauer-xl) var(--ov-ease-out) both;
    animation-delay: calc(var(--i, 0) * 40ms + var(--ov-delay, 0ms));
  }
  .is-visible .ov-linie, .ov-sofort .ov-linie, .ov-linie.ov-sofort {
.ov-tab-indikator {
  position: absolute;
  left: 0;
  width: 100px;
  transform-origin: 0 50%;
  transition: transform var(--ov-dauer-m) var(--ov-ease-out);
}
}

/* Muss den (ungelayerten) Reveal-Startzustand schlagen: Stagger-Eltern und
   reine Auslöser (Reveal dir="ohne", z. B. um Diagramme) bleiben stehen. */
.js-ready .ov-reveal[data-dir="ohne"]:not(.is-visible) { opacity: 1; transform: none; }
.js-ready .ov-reveal.ov-stagger:not(.is-visible) { opacity: 1; transform: none; }

